# Generated by llm-saea. See adjacent provenance JSON.
from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.7, 'crossover': 0.9, 'exploration': 0.35, 'local_fraction': 0.25, 'radius': 0.15, 'population': 30, 'generations': 5, 'reason': '24 of 100 evaluations done, so data is scarce and a sample-size-dependent choice is best; auto lets held-out RMSE pick RBF vs quadratic while rbf length-scale selection adds flexibility. Stagnation of 10 with zero recent improvement suggests we should avoid over-exploiting a poorly fit surrogate: raise exploration modestly and keep a moderate local_fraction so some search stays near the incumbent but not too concentrated. current_to_best DE balances exploitation of the best with directional diversity and is robust in 10D. Moderate mutation/crossover maintain diversity; population 30 and 5 generations keep surrogate refits cheap within the fixed budget. Radius 0.15 in normalized coordinates is a reasonable novelty scale for local sampling. No extra evaluations requested.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
